/**
 * TRUTH LEDGER — machine-readable source of truth for every factual claim.
 *
 * Rules (enforced by tests/content/claims.test.ts):
 *  - Any public data item that makes a factual claim references a ledger `id`.
 *  - Only entries with `publishable: true` may be referenced by public content.
 *  - Conflicting sources are documented, never averaged, merged or "rounded up".
 *
 * Human-readable version: docs/TRUTH-LEDGER.md (generated by `npm run docs:ledger`).
 */

export type ClaimStatus =
  | 'VERIFIED'
  | 'OWNER-CONFIRMED'
  | 'SELF-REPORTED'
  | 'THIRD-PARTY-CORROBORATED'
  | 'CONFLICTED'
  | 'UNVERIFIED'
  | 'DO-NOT-PUBLISH'

export type SourceType =
  | 'platform-verified' // computed or issued by the platform (ratings, levels, dates)
  | 'platform-self-reported' // written by Ring Lot on a third-party platform
  | 'client-review' // written by a client on a third-party platform
  | 'owner-brief' // provided by the site owner in the project brief
  | 'third-party-listing' // independent public listing (e.g. domain registration feeds)
  | 'search-absence' // searched for and not found

export type Confidence = 'high' | 'medium' | 'low'

export interface LedgerEntry {
  id: string
  claim: string
  source: string
  sourceUrl?: string
  sourceType: SourceType
  dateVerified: string
  confidence: Confidence
  status: ClaimStatus
  publishable: boolean
  notes: string
}

